<?php
use App\Support\ScaleLabel;
function weightLabel(string $body):string{$sum=0;for($i=0;$i<12;$i++)$sum+=(int)$body[$i]*($i%2===0?1:3);return $body.((10-$sum%10)%10);}
it('decodes configured EAN gram quantities exactly preserving product zeroes',function(){expect(ScaleLabel::decode(weightLabel('220012300750'),['prefix'=>'22','product_start'=>2,'product_length'=>5,'weight_start'=>7,'weight_length'=>5]))->toBe(['product_code'=>'00123','qty'=>'0.75','grams'=>750]);});
it('rejects corrupt check digits zero weights prefixes and overlapping positions',function(){ $p=['prefix'=>'22','product_start'=>2,'product_length'=>5,'weight_start'=>7,'weight_length'=>5];$label=weightLabel('220012300750');expect(fn()=>ScaleLabel::decode(substr($label,0,12).((int)$label[12]+1)%10,$p))->toThrow(InvalidArgumentException::class);expect(fn()=>ScaleLabel::decode(weightLabel('220012300000'),$p))->toThrow(InvalidArgumentException::class);expect(fn()=>ScaleLabel::decode(weightLabel('230012300750'),$p))->toThrow(InvalidArgumentException::class);expect(fn()=>ScaleLabel::validateProfile([...$p,'weight_start'=>6]))->toThrow(InvalidArgumentException::class);expect(fn()=>ScaleLabel::validateProfile([...$p,'weight_length'=>6]))->toThrow(InvalidArgumentException::class);});
